1	package com.example.starter.web;
2	
3	import com.example.starter.domain.AdjustmentTask;
4	import com.example.starter.domain.Assessment;
5	import com.example.starter.service.AdjustmentService;
6	import jakarta.validation.Valid;
7	import jakarta.validation.constraints.NotBlank;
8	import org.springframework.web.bind.annotation.GetMapping;
9	import org.springframework.web.bind.annotation.PathVariable;
10	import org.springframework.web.bind.annotation.PostMapping;
11	import org.springframework.web.bind.annotation.RequestBody;
12	import org.springframework.web.bind.annotation.RequestMapping;
13	import org.springframework.web.bind.annotation.RestController;
14	
15	/**
16	 * 调节任务流转入口：效果评估与归档。
17	 */
18	@RestController
19	@RequestMapping("/api/tasks")
20	public class TaskController {
21	
22	    private final AdjustmentService adjustmentService;
23	
24	    public TaskController(AdjustmentService adjustmentService) {
25	        this.adjustmentService = adjustmentService;
26	    }
27	
28	    /**
29	     * 评估请求。
30	     *
31	     * @param requestId 客户端幂等键
32	     */
33	    public record AssessmentRequest(@NotBlank String requestId) {
34	    }
35	
36	    /**
37	     * 查询任务详情。
38	     */
39	    @GetMapping("/{taskId}")
40	    public AdjustmentTask get(@PathVariable long taskId) {
41	        return adjustmentService.getTask(taskId);
42	    }
43	
44	    /**
45	     * 效果评估：稳定满 4 小时（恰满允许）后执行，requestId 幂等。
46	     */
47	    @PostMapping("/{taskId}/assessments")
48	    public Assessment assess(@PathVariable long taskId,
49	                             @Valid @RequestBody AssessmentRequest request) {
50	        return adjustmentService.assess(taskId, request.requestId());
51	    }
52	
53	    /**
54	     * 查询任务的评估记录（前后温度分布对比可复算）。
55	     */
56	    @GetMapping("/{taskId}/assessment")
57	    public Assessment assessment(@PathVariable long taskId) {
58	        return adjustmentService.getAssessmentByTask(taskId);
59	    }
60	
61	    /**
62	     * 归档：终态，重复归档幂等成功。
63	     */
64	    @PostMapping("/{taskId}/archive")
65	    public AdjustmentTask archive(@PathVariable long taskId) {
66	        return adjustmentService.archive(taskId);
67	    }
68	}
