170	                .orElseThrow(() -> new NotFoundException("调节任务不存在: taskId=" + taskId));
171	        switch (task.status()) {
172	            case EXECUTING -> {
173	                // 可评估
174	            }
175	            case ASSESSED -> throw new ConflictException("任务已评估: taskId=" + taskId);
176	            case ARCHIVED -> throw new ConflictException("任务已归档（终态），不允许评估: taskId=" + taskId);
177	            case MANUAL_REVIEW -> throw new ConflictException("任务已转人工复核，不允许评估: taskId=" + taskId);
