179	        }
180	        Instant now = clock.instant();
181	        Instant stabilizedAt = task.executedAt().plus(STABILIZATION);
182	        if (now.isBefore(stabilizedAt)) {
183	            throw new UnprocessableException("稳定期未满 4 小时，可评估时间(UTC): " + stabilizedAt);
184	        }
185	        BalanceService.BalanceView before = balanceService.evaluateBalance(
186	                task.stationId(), task.executedAt());
187	        BalanceService.BalanceView after = balanceService.evaluateBalance(task.stationId(), now);
