267	    /**
268	     * 前后温度分布对比，用于评估快照与复算。
269	     */
270	    public record Comparison(BalanceService.BalanceView before, BalanceService.BalanceView after) {
271	    }
272	
273	    static String fingerprint(String... parts) {
274	        try {
275	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
276	            byte[] hash = digest.digest(String.join("|", parts).getBytes(StandardCharsets.UTF_8));
277	            return HexFormat.of().formatHex(hash);
278	        } catch (NoSuchAlgorithmException e) {
279	            throw new IllegalStateException(e);
280	        }
281	    }
