20	 */
21	@Repository
22	public class AdjustmentTaskRepository {
23	
24	    private static final RowMapper<AdjustmentTask> MAPPER = (rs, n) -> new AdjustmentTask(
25	            rs.getLong("id"), rs.getLong("station_id"), rs.getLong("unit_id"),
26	            rs.getString("request_id"), rs.getString("fingerprint"),
27	            Optional.ofNullable(rs.getString("classification"))
28	                    .map(AdjustmentTask.ImbalanceType::valueOf).orElse(null),
29	            rs.getBigDecimal("step_percent"), rs.getBigDecimal("old_opening"),
30	            rs.getBigDecimal("new_opening"),
31	            AdjustmentTask.TaskStatus.valueOf(rs.getString("status")),
32	            Optional.ofNullable(rs.getTimestamp("executed_at")).map(Timestamp::toInstant).orElse(null),
33	            Optional.ofNullable(rs.getTimestamp("assessed_at")).map(Timestamp::toInstant).orElse(null),
34	            Optional.ofNullable(rs.getTimestamp("archived_at")).map(Timestamp::toInstant).orElse(null),
35	            rs.getTimestamp("created_at").toInstant());
36	
37	    private static final String COLUMNS = "id, station_id, unit_id, request_id, fingerprint,"
38	            + " classification, step_percent, old_opening, new_opening, status,"
39	            + " executed_at, assessed_at, archived_at, created_at";
40	
41	    private final JdbcTemplate jdbc;
42	
43	    public AdjustmentTaskRepository(JdbcTemplate jdbc) {
44	        this.jdbc = jdbc;
45	    }
46	
47	    /**
48	     * 插入任务并返回生成的主键。
49	     */
50	    public long insert(AdjustmentTask task) {
51	        KeyHolder keys = new GeneratedKeyHolder();
52	        jdbc.update(con -> {
53	            PreparedStatement ps = con.prepareStatement("INSERT INTO adjustment_task"
54	                            + " (station_id, unit_id, request_id, fingerprint, classification,"
55	                            + " step_percent, old_opening, new_opening, status,"
56	                            + " executed_at, assessed_at, archived_at, created_at)"
57	                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
58	                    Statement.RETURN_GENERATED_KEYS);
59	            ps.setLong(1, task.stationId());
60	            ps.setLong(2, task.unitId());
61	            ps.setString(3, task.requestId());
62	            ps.setString(4, task.fingerprint());
63	            ps.setString(5, task.classification() == null ? null : task.classification().name());
64	            ps.setBigDecimal(6, task.stepPercent());
65	            ps.setBigDecimal(7, task.oldOpening());
66	            ps.setBigDecimal(8, task.newOpening());
67	            ps.setString(9, task.status().name());
68	            ps.setTimestamp(10, task.executedAt() == null ? null : Timestamp.from(task.executedAt()));
69	            ps.setTimestamp(11, task.assessedAt() == null ? null : Timestamp.from(task.assessedAt()));
70	            ps.setTimestamp(12, task.archivedAt() == null ? null : Timestamp.from(task.archivedAt()));
71	            ps.setTimestamp(13, Timestamp.from(task.createdAt()));
72	            return ps;
73	        }, keys);
74	        return keys.getKey().longValue();
75	    }
76	
77	    /**
78	     * 按幂等键查询任务。
79	     */
80	    public Optional<AdjustmentTask> findByRequestId(String requestId) {
81	        return jdbc.query("SELECT " + COLUMNS + " FROM adjustment_task WHERE request_id = ?",
