package com.example.starter.domain;

import java.time.Instant;

/**
 * 阀门铅封台账行：每次登记/复封产生一行，保留历史封号链，同一阀门至多一行 ACTIVE。
 *
 * @param id           主键
 * @param valveId      阀门 ID
 * @param sealNo       铅封号，全局唯一，复封须换新号
 * @param valveVersion 封存时核对的开度版本号（阀门版本链从 1 开始，0 表示尚无版本）
 * @param sealedAt     封存时刻（UTC）
 * @param operatorA    登记人/复封核对人甲
 * @param operatorB    复封核对人乙，须与甲不同；首次登记时为 null
 * @param status       状态：ACTIVE 当前有效 / SUPERSEDED 已被复封取代（历史链）
 * @param requestId    客户端幂等键，全局唯一
 * @param fingerprint  幂等指纹：requestId 与全部业务字段的结构化 SHA-256
 * @param version      台账行版本，从 1 开始，成功变更（被取代）加 1
 * @param createdAt    登记时间（UTC）
 * @param updatedAt    最后变更时间（UTC）
 */
public record ValveSeal(long id, long valveId, String sealNo, int valveVersion, Instant sealedAt,
                        String operatorA, String operatorB, SealStatus status,
                        String requestId, String fingerprint, int version,
                        Instant createdAt, Instant updatedAt) {

    /**
     * 铅封台账状态机：ACTIVE → SUPERSEDED（复封取代，保留历史链）。
     */
    public enum SealStatus {
        /** 当前有效铅封。 */
        ACTIVE,
        /** 已被复封取代，仅作历史封号链保留。 */
        SUPERSEDED
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 临时解封单：两名不同授权人共同确认，固定 UTC 半开窗口与最多两次调节额度。
 *
 * @param id                   主键
 * @param valveId              阀门 ID
 * @param sealNo               引用的铅封号（批准时阀门的当前铅封）
 * @param expectedValveVersion 期望的下一开度版本号：批准时等于当前版本，每次消费随开度版本同步加 1
 * @param authorizerA          授权人甲
 * @param authorizerB          授权人乙，须与甲不同
 * @param windowStart          有效窗口起点（UTC），半开区间含起点
 * @param windowEnd            有效窗口终点（UTC），半开区间不含终点，恰到终点失效
 * @param quotaTotal           调节额度上限，最多 2 次
 * @param quotaUsed            已消费额度，仅在受控调节成功事务内加 1，失败不消费
 * @param status               状态：ACTIVE 生效中 / REVOKED 已撤销 / TERMINATED 复封终结
 * @param requestId            客户端幂等键，全局唯一
 * @param fingerprint          幂等指纹：requestId 与全部业务字段的结构化 SHA-256
 * @param version              解封单行版本，从 1 开始，成功变更（消费/撤销/终结）加 1
 * @param createdAt            批准时间（UTC）
 * @param updatedAt            最后变更时间（UTC）
 */
public record UnsealOrder(long id, long valveId, String sealNo, int expectedValveVersion,
                          String authorizerA, String authorizerB,
                          Instant windowStart, Instant windowEnd,
                          int quotaTotal, int quotaUsed, OrderStatus status,
                          String requestId, String fingerprint, int version,
                          Instant createdAt, Instant updatedAt) {

    /**
     * 解封单状态机：ACTIVE → REVOKED（撤销）或 TERMINATED（复封终结）。
     */
    public enum OrderStatus {
        /** 生效中：窗口内且额度足够时允许受控调节。 */
        ACTIVE,
        /** 已撤销：不再允许新的受控调节。 */
        REVOKED,
        /** 复封终结：复封时原子终结，不再允许新的受控调节。 */
        TERMINATED
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 解封额度轨迹事件：授予/消费/撤销/终结，与业务变更同事务写入。
 *
 * @param id        主键
 * @param orderId   所属解封单 ID
 * @param valveId   阀门 ID
 * @param eventType 事件类型：GRANT 授予 / CONSUME 消费 / REVOKE 撤销 / TERMINATE 复封终结
 * @param quotaUsed 事件发生后已用额度
 * @param taskId    消费事件对应的调节任务 ID；非消费事件为 null
 * @param detail    事件说明（合成数据）
 * @param createdAt 事件时间（UTC）
 */
public record UnsealQuotaEvent(long id, long orderId, long valveId, EventType eventType,
                               int quotaUsed, Long taskId, String detail, Instant createdAt) {

    /**
     * 额度轨迹事件类型。
     */
    public enum EventType {
        /** 授予：解封批准，额度生效。 */
        GRANT,
        /** 消费：受控调节成功，额度减一。 */
        CONSUME,
        /** 撤销：解封单被撤销，剩余额度作废。 */
        REVOKE,
        /** 复封终结：复封原子终结解封权限，剩余额度作废。 */
        TERMINATE
    }
}

package com.example.starter.service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.HexFormat;

/**
 * 结构化幂等指纹：对每个字段做长度前缀编码后再取 SHA-256，
 * 字段值本身含分隔符（如 "|"、":"）时仍无歧义，合法文本不会被拼接混淆。
 */
public final class Fingerprints {

    private Fingerprints() {
    }

    /**
     * 由全部业务字段计算结构化指纹；null 字段以 -1 长度标记编码，与空串区分。
     */
    public static String of(String... parts) {
        StringBuilder canonical = new StringBuilder();
        for (String part : parts) {
            if (part == null) {
                canonical.append("-1:");
            } else {
                canonical.append(part.length()).append(':').append(part);
            }
            canonical.append('|');
        }
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(canonical.toString().getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /**
     * 精确时刻字段编码：ISO-8601 UTC 文本，null 传递为 null 以区别于任意合法时刻。
     */
    public static String at(Instant instant) {
        return instant == null ? null : instant.toString();
    }
}

