    public Optional<Valve> findById(long id) {
        return jdbc.query("SELECT id, unit_id, opening_percent, updated_at FROM valve WHERE id = ?",
                MAPPER, id).stream().findFirst();
    }

    /**
     * 更新阀门当前开度；必须与版本记录在同一事务内调用。
